TASK:
Rewrite ONLY DIFFERENTIATE rows so they become clearly distinct while keeping the locked keyword fields unchanged.

Return ONLY valid JSON matching the required schema.

parameters.jsCode:
const originalItems = $('Apply Auditor Changes').all();
const originalMap = {};

originalItems.forEach(item => {
  const id = item.json['Row ID'] || item.json.row_id;
  if (id) originalMap[id] = item.json;
});

const raw = $input.first().json.output;
let agentResult;

try {
  agentResult = typeof raw === 'string' ? JSON.parse(raw) : raw;
} catch (e) {
  const match = String(raw).match(/\{[\s\S]*\}/);
  if (match) {
    agentResult = JSON.parse(match[0]);
  } else {
    throw new Error('No valid JSON in rewrite_plan output.');
  }
}

const patches = agentResult.patches || [];
const patchMap = {};
patches.forEach(p => {
  patchMap[p.row_id] = p;
});

const result = [];

for (const item of originalItems) {
  const row = { ...item.json };
  const rowId = row['Row ID'] || row.row_id;
  const action = row['Audit Action'];
  const patch = patchMap[rowId];

  if (action === 'DIFFERENTIATE' && patch) {
    if (patch['Blog Post Title']) row['Blog Post Title'] = patch['Blog Post Title'];
    if (patch['Blog Slug']) row['Blog Slug'] = patch['Blog Slug'];
    if (patch['Content Brief']) row['Content Brief'] = patch['Content Brief'];

    row['Audit Action'] = 'KEEP';
    row['_rewrite_applied'] = true;
  }

  result.push({ json: row });
}

return result;

// Filter Output Fields
// Type: Code node
// Mode: Run Once for All Items
//
// Purpose:
// - Keep final 6 visible content plan fields.
// - Preserve hidden metadata for callback / downstream package.
// - Preserve language metadata.
// - Do not add extra visible Google Sheet columns downstream.

const items = $input.all();

function firstJson(nodeName) {
  try {
    return $(nodeName).first().json || {};
  } catch (e) {
    return {};
  }
}

function clean(value) {
  return String(value ?? '').replace(/\s+/g, ' ').trim();
}

function firstNonEmpty(...values) {
  for (const value of values) {
    const s = clean(value);
    if (s) return s;
  }
  return null;
}

const trigger = firstJson('When Executed by Another Workflow');
const normalizeWriter = firstJson('Normalize Writer Input');

const callbackUrl = firstNonEmpty(trigger.callback_url, normalizeWriter.callback_url);
const taskId = firstNonEmpty(trigger.taskId, normalizeWriter.taskId);
const brandId = firstNonEmpty(trigger.brandId, normalizeWriter.brandId);
const userId = firstNonEmpty(trigger.userId, normalizeWriter.userId);

const clientName =
  firstNonEmpty(
    trigger.client_name,
    trigger.company_name,
    normalizeWriter.client_name,
    normalizeWriter.company_name
  );

const spreadsheetId =
  firstNonEmpty(
    trigger.spreadsheet_id,
    trigger.spreadsheetId,
    normalizeWriter.spreadsheet_id
  );

const spreadsheetUrl =
  firstNonEmpty(
    trigger.spreadsheet_url,
    normalizeWriter.spreadsheet_url,
    spreadsheetId ? `https://docs.google.com/spreadsheets/d/${spreadsheetId}/edit` : ''
  );

const languageDefaults = {
  content_plan_language: firstNonEmpty(trigger.content_plan_language, normalizeWriter.content_plan_language, 'English'),
  content_plan_language_code: firstNonEmpty(trigger.content_plan_language_code, normalizeWriter.content_plan_language_code, trigger.serper_hl, normalizeWriter.serper_hl, 'en'),
  content_plan_language_key: firstNonEmpty(trigger.content_plan_language_key, normalizeWriter.content_plan_language_key, 'english'),
  google_ads_language: firstNonEmpty(trigger.google_ads_language, normalizeWriter.google_ads_language, trigger.language, normalizeWriter.language, 'languageConstants/1000'),
  google_ads_language_id: firstNonEmpty(trigger.google_ads_language_id, normalizeWriter.google_ads_language_id, '1000'),
  google_ads_language_code: firstNonEmpty(trigger.google_ads_language_code, normalizeWriter.google_ads_language_code, trigger.content_plan_language_code, normalizeWriter.content_plan_language_code, 'en'),
  planner_language_scope: firstNonEmpty(trigger.planner_language_scope, normalizeWriter.planner_language_scope, trigger.content_plan_language_code, normalizeWriter.content_plan_language_code, 'en'),
  serper_hl: firstNonEmpty(trigger.serper_hl, normalizeWriter.serper_hl, trigger.content_plan_language_code, normalizeWriter.content_plan_language_code, 'en'),
  serper_gl: firstNonEmpty(trigger.serper_gl, normalizeWriter.serper_gl),
};

return items.map(item => {
  const d = item.json || {};

  return {
    json: {
      'Target Keyword': clean(d['Target Keyword']),
      'Semantic Keyword 1': clean(d['Semantic Keyword 1']),
      'Semantic Keyword 2': clean(d['Semantic Keyword 2']),
      'Blog Post Title': clean(d['Blog Post Title']),
      'Blog Slug': clean(d['Blog Slug']),
      'Content Brief': clean(d['Content Brief']),

      callback_url: callbackUrl,
      taskId,
      brandId,
      userId,
      client_name: clientName,
      spreadsheet_id: spreadsheetId,
      spreadsheet_url: spreadsheetUrl,

      content_plan_language: d.content_plan_language || languageDefaults.content_plan_language,
      content_plan_language_code: d.content_plan_language_code || languageDefaults.content_plan_language_code,
      content_plan_language_key: d.content_plan_language_key || languageDefaults.content_plan_language_key,
      google_ads_language: d.google_ads_language || languageDefaults.google_ads_language,
      google_ads_language_id: d.google_ads_language_id || languageDefaults.google_ads_language_id,
      google_ads_language_code: d.google_ads_language_code || languageDefaults.google_ads_language_code,
      planner_language_scope: d.planner_language_scope || languageDefaults.planner_language_scope,
      serper_hl: d.serper_hl || languageDefaults.serper_hl,
      serper_gl: d.serper_gl || languageDefaults.serper_gl,
      language: d.language || d.google_ads_language || languageDefaults.google_ads_language,
    },
  };
});

// Prepare Egor Callback Payload
// Type: Code node
// Mode: Run Once for All Items
//
// Purpose:
// - Send final SEO Content Plan rows to backend in Igor's requested camelCase DTO.
// - Preserve taskId, brandId, userId.
// - Keep egor-test-callback unchanged: it still sends $json.body.
// - Input is expected from Filter Output Fields.

const items = $input.all();

const DEFAULT_CALLBACK_URL = 'https://backend-production.snoika.com/n8n/webhook/keywords';

function firstJson(nodeName) {
  try {
    return $(nodeName).first().json || {};
  } catch (e) {
    return {};
  }
}

function allJson(nodeName) {
  try {
    return $(nodeName).all().map(i => i.json || {});
  } catch (e) {
    return [];
  }
}

function clean(value) {
