  }
  return null;
}

function isValidUrl(value) {
  const s = clean(value);
  return /^https?:\/\/[^\s]+$/i.test(s);
}

function pickCallbackUrl(...values) {
  for (const value of values) {
    const s = clean(value);
    if (isValidUrl(s)) return s;
