function getLanguageInfo(...sources) {
  const contentPlanLanguage =
    firstNonEmpty(
      ...sources.map(s => s?.content_plan_language),
      ...sources.map(s => s?.language?.content_plan_language),
      ...sources.map(s => s?.['Content Plan Language']),
