}

function compactKeywordInput(row) {
  const meta = row.keyword_metadata || {};
  const languageInfo = getLanguageInfo(row, meta);

  const keyword = cleanOrNull(
    row.core_keyword ||
    row.keyword ||
    row['Target Keyword'] ||
    row.target_keyword ||
    meta.keyword
  );

  const clusterLabel = cleanOrNull(
    row.cluster_label ||
    row.cluster_name ||
    row['Cluster Name'] ||
    row.cluster ||
    meta.cluster_label ||
    'Unclustered'
  );

  return {
    execution_id: cleanOrNull(row.execution_id),

    keyword,
    core_keyword: keyword,
    cluster_label: clusterLabel,

    search_volume: num(row.core_search_volume ?? row.search_volume ?? meta.search_volume),
    competition: cleanOrNull(row.core_competition ?? row.competition ?? meta.competition),
    competition_index: num(row.core_competition_index ?? row.competition_index ?? meta.competition_index),
    yoy_6_v6: num(row.core_yoy_6_v6 ?? row.yoy_6_v6 ?? meta.yoy_6_v6),
    strategy_name: cleanOrNull(row.strategy_name || row.core_strategy_name || meta.strategy_name),
    strategy_names: arr(row.strategy_names || row.core_strategy_names || meta.strategy_names),

    semantic_1_keyword: cleanOrNull(
      row.semantic_1_keyword ||
      row.semantic_1 ||
      row['Semantic Keyword 1'] ||
      meta.semantic_1_keyword
    ),

    semantic_2_keyword: cleanOrNull(
      row.semantic_2_keyword ||
      row.semantic_2 ||
      row['Semantic Keyword 2'] ||
      meta.semantic_2_keyword
    ),

    source: cleanOrNull(row.source ?? meta.source),
