function buildClusterSummary(selectedKeywordRows, finalRows) {
  const map = {};

  for (const row of selectedKeywordRows) {
    const cluster = clean(row.cluster_label || row.cluster_name || 'Unclustered') || 'Unclustered';

    if (!map[cluster]) {
      map[cluster] = {
        cluster_label: cluster,
        selected_keyword_count: 0,
        final_content_row_count: 0,
        keywords: [],
        final_titles: [],
        final_slugs: [],
      };
    }

    map[cluster].selected_keyword_count += 1;

    if (row.keyword) {
      map[cluster].keywords.push({
        keyword: row.keyword,
        search_volume: row.search_volume,
        competition: row.competition,
        competition_index: row.competition_index,
        yoy_6_v6: row.yoy_6_v6,
        strategy_name: row.strategy_name,
        source: row.source,
        source_domain: row.source_domain,
      });
    }
  }

  for (const row of finalRows) {
    const cluster = clean(row.cluster_label || row['Cluster Name'] || 'Unclustered') || 'Unclustered';

    if (!map[cluster]) {
      map[cluster] = {
        cluster_label: cluster,
        selected_keyword_count: 0,
        final_content_row_count: 0,
        keywords: [],
        final_titles: [],
        final_slugs: [],
      };
    }

    map[cluster].final_content_row_count += 1;

    if (row['Blog Post Title']) map[cluster].final_titles.push(row['Blog Post Title']);
    if (row['Blog Slug']) map[cluster].final_slugs.push(row['Blog Slug']);
  }

  return Object.values(map).map(cluster => ({
    ...cluster,
    final_titles: uniq(cluster.final_titles),
    final_slugs: uniq(cluster.final_slugs),
  }));
}

function buildRowsForSheet(rows) {
  return rows.map(row => ({
    'Target Keyword': clean(row['Target Keyword']),
    'Semantic Keyword 1': clean(row['Semantic Keyword 1']),
    'Semantic Keyword 2': clean(row['Semantic Keyword 2']),
    'Blog Post Title': clean(row['Blog Post Title']),
    'Blog Slug': clean(row['Blog Slug']),
    'Content Brief': clean(row['Content Brief']),
  }));
}

