// Competitor SERP Research
// Type: Code node
// Mode: Run Once for Each Item (one keyword per loop iteration)
//
// Purpose:
// - Build one Perplexity competitor-intelligence request.
// - Use existing SERP snapshot + keyword + business context.
// - Make competitor intelligence language-aware.
// - Return _competitor_body for the Perplexity HTTP Request.

const row = $input.first().json || {};

function clean(value) {
  return String(value ?? '').replace(/\s+/g, ' ').trim();
}

function take(arr, limit) {
  return Array.isArray(arr) ? arr.slice(0, limit) : [];
}

function firstNonEmpty(...values) {
  for (const value of values) {
    const s = clean(value);
    if (s) return s;
  }
  return null;
}

const coreKeyword = clean(row.core_keyword);
