// Parse Competitor SERP Research
// Mode: Run Once for Each Item (one keyword per loop iteration)
//
// Purpose:
// - Parse the Perplexity competitor research response.
// - Return original row + competitor_intelligence.
// - If parsing fails, return safe low-confidence competitor_intelligence.

const response = $input.first().json || {};

let originalRow = {};
try {
  originalRow = $('Competitor SERP Research').item.json || {};
} catch (e) {
  try {
    originalRow = $('Competitor SERP Research').first().json || {};
  } catch (e2) {
    originalRow = {};
  }
}

function clean(value) {
  return String(value ?? '').replace(/\s+/g, ' ').trim();
}

function safeArray(value) {
  return Array.isArray(value) ? value : [];
}

function safeParseJson(raw) {
  if (!raw) return null;

  if (typeof raw === 'object' && !Array.isArray(raw)) return raw;

  const text = String(raw)
    .replace(/^```(?:json)?\s*/i, '')
    .replace(/\s*```$/i, '')
    .trim();

  const match = text.match(/\{[\s\S]*\}/);
  const candidate = match ? match[0] : text;

  try {
    return JSON.parse(candidate);
  } catch (e) {
    return null;
  }
}

function defaultCompetitorIntel(reason) {
  return {
    dominant_h2_patterns: [],
    common_subtopics: [],
    content_approach_distribution: {
      technical: 0,
      'beginner-friendly': 0,
      'practical-examples': 0,
      'sales-oriented': 0,
      mixed: 0,
      other: 0,
    },
    article_types_distribution: {
      guide: 0,
      'how-to': 0,
      listicle: 0,
      comparison: 0,
      explainer: 0,
      'service-page': 0,
      'landing-page': 0,
      'case-study': 0,
      other: 0,
    },
    avg_word_count: 0,
    recommended_length: '',
    proof_patterns: {
      use_statistics: false,
      use_expert_quotes: false,
      use_case_studies: false,
      use_named_tools: false,
      use_step_by_step: false,
    },
    coverage_gaps: [],
    recurring_faq_questions: [],
    unique_angle_opportunity: '',
    confidence: 'low',
    confidence_note: reason || 'No reliable competitor intelligence returned.',
  };
}

const content =
  response?.choices?.[0]?.message?.content ||
  response?.output ||
  response?.text ||
  '';

const parsed = safeParseJson(content);

const rawIntel =
  parsed?.competitor_intelligence ||
  parsed?.competitorIntelligence ||
  parsed ||
  null;

let competitorIntel = rawIntel && typeof rawIntel === 'object'
  ? rawIntel
  : defaultCompetitorIntel('Could not parse Perplexity competitor research JSON.');

competitorIntel = {
  dominant_h2_patterns: safeArray(competitorIntel.dominant_h2_patterns),
  common_subtopics: safeArray(competitorIntel.common_subtopics),
  content_approach_distribution: competitorIntel.content_approach_distribution || {},
  article_types_distribution: competitorIntel.article_types_distribution || {},
  avg_word_count: Number(competitorIntel.avg_word_count || 0),
  recommended_length: clean(competitorIntel.recommended_length),
  proof_patterns: competitorIntel.proof_patterns || {},
  coverage_gaps: safeArray(competitorIntel.coverage_gaps),
  recurring_faq_questions: safeArray(competitorIntel.recurring_faq_questions),
  unique_angle_opportunity: clean(competitorIntel.unique_angle_opportunity),
  confidence: clean(competitorIntel.confidence || 'low'),
  confidence_note: clean(competitorIntel.confidence_note),
};

return [
  {
    json: {
      ...originalRow,
      competitor_intelligence: competitorIntel,
    },
  },
];

// Prepare Research Agent Input
// Type: Code node
// Mode: Run Once for Each Item
//
// Builds one compact research_agent_input per keyword row for the
// Research & Plan Agent. Only planning-relevant data goes to the agent;
// sheet/callback metadata stays on the row.

const row = $json || {};

function clean(value) {
  return String(value ?? '').replace(/\s+/g, ' ').trim();
}

function firstNonEmpty(...values) {
  for (const value of values) {
    const s = clean(value);
    if (s) return s;
  }
  return null;
}

function list(value, limit) {
  if (!Array.isArray(value)) return [];

  return value
    .map(v => (typeof v === 'string' ? clean(v) : v))
    .filter(v => {
      if (typeof v === 'string') return Boolean(v);
      if (v && typeof v === 'object') return Object.keys(v).length > 0;
      return v !== null && v !== undefined;
    })
    .slice(0, limit);
}

const language = {
  content_plan_language: firstNonEmpty(row.content_plan_language, 'English'),
  content_plan_language_code: firstNonEmpty(row.content_plan_language_code, row.serper_hl, 'en'),
  serper_hl: firstNonEmpty(row.serper_hl, row.content_plan_language_code, 'en'),
};

const companyContext = row.company_context || {};
const company = companyContext.company || {};
const seo = companyContext.seo_context || {};
const positioning = companyContext.positioning || {};
const guardrails = companyContext.guardrails || {};
const serp = row.serp_data || {};
const serpIntel =
  row.competitor_intelligence && typeof row.competitor_intelligence === 'object'
    ? row.competitor_intelligence
    : null;

// Rows already produced in earlier loop iterations of THIS execution.
// Replaces the old workflowStaticData memory: run-scoped, so nothing
// leaks between executions. Accessing a run index that does not exist
// throws, which ends the collection loop.
const previousRows = [];
try {
  for (let runIndex = 0; runIndex < 1000; runIndex++) {
    for (const it of $('Parse Research Agent Output').all(0, runIndex)) {
      const j = it.json || {};
      if (!clean(j['Target Keyword'])) continue;
      previousRows.push({
        keyword: clean(j['Target Keyword']),
        title: clean(j['Blog Post Title']),
        unique_angle: clean(j.unique_angle),
        main_point: clean(j.article_main_point),
        purpose: clean(j.article_purpose),
      });
    }
  }
} catch (e) {
  // no more runs
}

const icpSegments = list(companyContext.icp_segments_summary || [], 4).map(seg => ({
  segment_name: clean(seg.segment_name || ''),
  geography: list(seg.geography || [], 5),
  industry: list(seg.industry || [], 6),
  buyer_roles: list(seg.buyer_roles || [], 7),
  pain_points: list(seg.pain_points || [], 7),
  desired_outcomes: list(seg.desired_outcomes || [], 7),
  relevant_offers: list(seg.relevant_offers || [], 6),
}));

const research_agent_input = {
  language,

  locked_fields: {
    target_keyword: clean(row.core_keyword),
    semantic_keyword_1: clean(row.semantic_1_keyword),
    semantic_keyword_2: clean(row.semantic_2_keyword),
  },

  keyword: {
    cluster_label: clean(row.cluster_label),
    search_volume: row.core_search_volume || 0,
    competition_index: row.core_competition_index || null,
    yoy_6_v6: row.core_yoy_6_v6 || null,
    semantic_roles: [
      { keyword: clean(row.semantic_1_keyword), role: clean(row.semantic_1_reason || row.semantic_1_type) },
      { keyword: clean(row.semantic_2_keyword), role: clean(row.semantic_2_reason || row.semantic_2_type) },
    ].filter(x => x.keyword),
  },

  company: {
    name: clean(row.company_name || company.name),
    client_url: clean(row.client_url),
    business_summary: clean(company.business_summary),
    primary_offers: list(company.primary_offers || [], 6),
    strategic_focus: list(company.strategic_focus || [], 6),
    differentiators: list(positioning.differentiators || [], 6),
    value_props: list(positioning.value_props || [], 6),
    messages_hooks: list(positioning.messages_hooks || [], 5),
  },

  audience: {
    icp_segments: icpSegments,
    best_fit_intents: list(seo.best_fit_intents || [], 7),
    industry_modifiers: list(seo.industry_modifiers || [], 8),
    geo_modifiers: list(seo.geo_modifiers || [], 8),
    audience_modifiers: list(seo.audience_modifiers || [], 8),
  },

  constraints: {
    compliance_restrictions: list(guardrails.compliance_restrictions || [], 8),
    topics_to_avoid: list(guardrails.topics_to_avoid || [], 8),
    claims_to_qualify_or_avoid: list(guardrails.claims_to_qualify_or_avoid || [], 8),
    competitor_keyword_policy: clean(guardrails.competitor_keyword_policy),
  },

  serp_snapshot: {
    top_results: list(serp.organic || [], 6)
      .map(r => ({ position: r.position, title: clean(r.title), link: clean(r.link), snippet: clean(r.snippet) }))
      .filter(r => r.title || r.snippet),
    people_also_ask: list((serp.peopleAlsoAsk || []).map(x => x.question).filter(Boolean), 7),
    related_searches: list((serp.relatedSearches || []).map(x => x.query).filter(Boolean), 9),
  },

  serp_competitor_intelligence: serpIntel ? {
    dominant_h2_patterns: list(serpIntel.dominant_h2_patterns || [], 8),
    common_subtopics: list(serpIntel.common_subtopics || [], 8),
    coverage_gaps: list(serpIntel.coverage_gaps || [], 8),
    recurring_faq_questions: list(serpIntel.recurring_faq_questions || [], 6),
    unique_angle_opportunity: clean(serpIntel.unique_angle_opportunity),
    recommended_length: clean(serpIntel.recommended_length),
    confidence: clean(serpIntel.confidence || 'low'),
    confidence_note: clean(serpIntel.confidence_note),
  } : null,

  previously_created_rows: previousRows.slice(-30),
};

return {
  json: {
    ...row,
    research_agent_input,
  },
};

// Parse Research Agent Output
// Type: Code node
// Mode: Run Once for Each Item
//
// - Parses the Research & Plan Agent JSON output.
// - Restores locked keyword fields from Prepare Research Agent Input
//   (the agent is never trusted with them).
// - Unicode-safe slug fallback.
// - Emits the row shape expected by build_audit_dataset plus the
//   research/strategy metadata used by the handoff package.

const aiResponse = $json || {};

let originalData = {};
try {
  originalData = $('Prepare Research Agent Input').item.json || {};
} catch (e) {
  // Inside the keyword loop there is exactly one item per iteration,
  // so the first item is always the matching row.
  try {
    originalData = $('Prepare Research Agent Input').first().json || {};
  } catch (e2) {
    originalData = {};
  }
}

function clean(value) {
  return String(value ?? '').replace(/\s+/g, ' ').trim();
}

function firstNonEmpty(...values) {
  for (const value of values) {
    const s = clean(value);
    if (s) return s;
  }
  return null;
}

function safeArray(value) {
  return Array.isArray(value) ? value : [];
}

function slugify(value) {
  return clean(value)
    .toLowerCase()
    .normalize('NFC')
    .replace(/&/g, ' and ')
    .replace(/[^\p{L}\p{N}\s-]/gu, '')
    .replace(/\s+/g, '-')
    .replace(/-+/g, '-')
    .replace(/^-|-$/g, '');
}

function extractJson(raw) {
  if (raw && typeof raw === 'object' && !Array.isArray(raw)) {
    if (raw.output) return extractJson(raw.output);
    return raw;
  }

  const text = String(raw ?? '')
    .replace(/^```(?:json)?\s*/i, '')
    .replace(/\s*```$/i, '')
    .trim();

  const match = text.match(/\{[\s\S]*\}/);
  const candidate = match ? match[0] : text;

  return JSON.parse(candidate);
}

let aiParsed = {};
let parseFailed = false;
const aiText = aiResponse.output || aiResponse.text || aiResponse.result || JSON.stringify(aiResponse);

try {
  aiParsed = extractJson(aiText);
} catch (error) {
  aiParsed = {};
  parseFailed = true;
}

const targetKeyword = clean(originalData.core_keyword);
const semantic1 = clean(originalData.semantic_1_keyword);
const semantic2 = clean(originalData.semantic_2_keyword);

const blogTitle = clean(aiParsed['Blog Post Title']) || targetKeyword;

let blogSlug = clean(aiParsed['Blog Slug']) || slugify(targetKeyword);
blogSlug = slugify(blogSlug) || slugify(targetKeyword);

const contentBrief = clean(aiParsed['Content Brief']);

const researchSummary =
  aiParsed.research_summary && typeof aiParsed.research_summary === 'object'
    ? aiParsed.research_summary
    : {};

const searchIntent = clean(aiParsed.search_intent) || 'other';
const journeyStage = clean(aiParsed.journey_stage) || 'MoFu';
const uniqueAngle = clean(aiParsed.unique_angle);
const whyNowHook = clean(aiParsed.why_now_hook);

const contentPlanLanguage = firstNonEmpty(originalData.content_plan_language, 'English');
const contentPlanLanguageCode = firstNonEmpty(originalData.content_plan_language_code, originalData.serper_hl, 'en');

// Deterministic SERP analysis done before the agent (Parse Competitor
// SERP Research). The agent findings enrich it; they never replace it.
const serpIntel =
  originalData.competitor_intelligence && typeof originalData.competitor_intelligence === 'object'
    ? originalData.competitor_intelligence
    : null;

function mergeUnique(a, b, limit) {
  const out = [];
  const seen = new Set();
  for (const v of [...safeArray(a), ...safeArray(b)]) {
    const s = clean(typeof v === 'string' ? v : JSON.stringify(v));
    if (!s) continue;
    const k = s.toLowerCase();
    if (seen.has(k)) continue;
    seen.add(k);
    out.push(typeof v === 'string' ? s : v);
  }
  return out.slice(0, limit);
}

return {
  json: {
    ...originalData,

    'Target Keyword': targetKeyword,
    'Semantic Keyword 1': semantic1,
    'Semantic Keyword 2': semantic2,
    'Blog Post Title': blogTitle,
    'Blog Slug': blogSlug,
    'Content Brief': contentBrief,

    'Client': originalData.company_name || '',
    'Cluster Name': originalData.cluster_label || '',
    'Primary Intent': searchIntent,
    'Stage': journeyStage,

    search_intent: searchIntent,
    journey_stage: journeyStage,
    target_audience: clean(aiParsed.target_audience),
    reader_problem: clean(aiParsed.reader_problem),
    unique_angle: uniqueAngle,
    article_main_point: clean(aiParsed.main_point),
    article_purpose: clean(aiParsed.purpose),
    title_direction: uniqueAngle,
    slug_basis: blogSlug,
    why_now_hook: whyNowHook,

    must_cover_topics: mergeUnique(serpIntel?.common_subtopics, researchSummary.coverage_gaps, 8),
    faq_questions_from_research: mergeUnique(serpIntel?.recurring_faq_questions, researchSummary.audience_questions, 8),
    competitor_gaps_to_exploit: mergeUnique(serpIntel?.coverage_gaps, researchSummary.coverage_gaps, 8),

    competitor_intelligence: {
      ...(serpIntel || {}),
      dominant_h2_patterns: mergeUnique(serpIntel?.dominant_h2_patterns, researchSummary.competitor_patterns, 8),
      common_subtopics: safeArray(serpIntel?.common_subtopics).slice(0, 8),
      coverage_gaps: mergeUnique(serpIntel?.coverage_gaps, researchSummary.coverage_gaps, 8),
      recurring_faq_questions: mergeUnique(serpIntel?.recurring_faq_questions, researchSummary.audience_questions, 6),
      unique_angle_opportunity: uniqueAngle || clean(serpIntel?.unique_angle_opportunity),
      confidence: clean(serpIntel?.confidence) || clean(researchSummary.confidence) || (parseFailed ? 'low' : 'medium'),
      confidence_note: parseFailed
        ? 'Research & Plan Agent output could not be parsed.'
        : clean(serpIntel?.confidence_note),
    },

    socials_research: {
      social_signal_quality: safeArray(researchSummary.audience_questions).length ? 'medium' : 'none',
      audience_questions: safeArray(researchSummary.audience_questions).slice(0, 8),
      pain_patterns: [],
      language_patterns: [],
      research_notes: '',
    },

    news_research: {
      recency_relevant: Boolean(whyNowHook),
      timing_hooks: safeArray(researchSummary.timing_hooks).slice(0, 5),
      news_items: [],
      official_signals: [],
      research_notes: '',
    },

    content_plan_language: contentPlanLanguage,
    content_plan_language_code: contentPlanLanguageCode,

    parse_debug: {
      agent_output_parse_failed: parseFailed,
      locked_keywords_restored_from_input: true,
      slug_unicode_safe: true,
    },
  },
};
